const query = $input.item.json.query || {};
const verifyToken = process.env.META_VERIFY_TOKEN || 'my_secure_whatsapp_verify_token_2026';

const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];

if (mode === 'subscribe' && token === verifyToken) {
  return [{ json: { body: challenge } }];
} else {
  return [{ json: { body: 'Verification failed: invalid token or mode', status: 403 } }];
}

const body = $input.item.json.body;

// 1. Validate payload structure
if (!body || typeof body !== 'object' || !body.entry || !Array.isArray(body.entry) || body.entry.length === 0) {
  return [{ json: { isValid: false, reason: 'Invalid or missing entry payload structure' } }];
}

const changes = body.entry[0].changes;
if (!changes || !Array.isArray(changes) || changes.length === 0 || !changes[0].value) {
  return [{ json: { isValid: false, reason: 'Missing change value payload' } }];
}

const value = changes[0].value;
if (!value.messages || !Array.isArray(value.messages) || value.messages.length === 0) {
  return [{ json: { isValid: false, reason: 'Status delivery update or empty message (ignored)' } }];
}

const message = value.messages[0];
const contact = value.contacts && value.contacts.length > 0 ? value.contacts[0] : {};

// 2. Limit accepted message types: text only
if (message.type !== 'text' || !message.text || !message.text.body || message.text.body.trim() === '') {
  return [{ json: { isValid: false, reason: `Unsupported message type '${message.type}' (accepted: text only)` } }];
}

return [{
  json: {
    isValid: true,
    whatsapp_message_id: message.id,
    phone_number: message.from,
    customer_name: contact.profile ? contact.profile.name : 'WhatsApp User',
    message_text: message.text.body.trim(),
    message_type: message.type,
    timestamp: message.timestamp
  }
}];

