try {
  const responseText = $input.item.json.response;
  const parsed = JSON.parse(responseText);
  return [{ json: { success: true, ai_output: parsed } }];
} catch (e) {
  return [{
    json: {
      success: false,
      ai_output: {
        reply: 'Thank you for your message. We are experiencing a temporary technical issue. A team member will assist you shortly.',
        lead_ready: true,
        human_handoff: true,
        handoff_reason: 'AI JSON Parse Error',
        lead_score: 50,
        lead: {}
      }
    }
  }];
}

return [{
